css:
:root {
  --bg: #f0f5ec;
  --surface: #fafcf8;
  --border: #b8cfb0;
  --text: #24331f;
  --text-medium: #40543a;
  --text-muted: #5f7358;
  --text-ghost: #8fa68a;
}
:root.dark {
  --bg: #141f10;
  --surface: #1c2b17;
  --border: #35492e;
  --text: #e6efe0;
  --text-medium: #c2d4b8;
  --text-muted: #93a98a;
  --text-ghost: #667a5e;
}
body { background: var(--bg); }
.card-tile { border: 1px solid var(--border); border-radius: 8px; }
.card-tile:hover { border-color: #4a8c3f; }
.card-tag { background: #4a8c3f; color: #ffffff; border-radius: 10px; }
.header { border-bottom: 2px solid var(--border); }
